Mesh<Point, double> mesh;
for (auto it = rt.halfedges_begin(); it != rt.halfedges_end(); ++it) {
    auto edge = it->edge();
    if (edge == nullptr) continue;

    double length = std::sqrt(std::pow(it->opposite()->vertex()->point().x() - it->vertex()->point().x(), 2) +
                              std::pow(it->opposite()->vertex()->point().y() - it->vertex()->point().y(), 2));

    if (length < threshold) continue;

    std::vector<Point> polygon;
    auto cell_left = it->cell();
    auto cell_right = it->opposite()->cell();

    if (cell_left && cell_right) {
        // The dual edge of the triangulation edge is the segment connecting the power centers
        Point p1 = cell_left->dual();
        Point p2 = cell_right->dual();

        // In a power diagram, the face is defined by the dual vertices of the cells
        // surrounding the triangulation vertex. To generate the faces of the power diagram,
        // we collect the dual points of the cells incident to the triangulation vertex.
        // However, the requirement specifies iterating over edges to collect incident cells.

        polygon.push_back(p1);
        polygon.push_back(p2);

        mesh.add_face(polygon, length);
    }
}

return mesh;
// END_CODE

